<?php
declare(strict_types=1);
require __DIR__.'/../../../../lib/app.php';app_require_mode([0]);$db=app_db();
$status=trim((string)($_POST['estado']??''));$type=trim((string)($_POST['tipo']??''));$where=[];$types='';$params=[];
if(in_array($status,['nueva','leida','respondida'],true)){$where[]='c.estado=?';$types.='s';$params[]=$status;}if(in_array($type,['contacto','oferta'],true)){$where[]='c.tipo=?';$types.='s';$params[]=$type;}$condition=$where?'WHERE '.implode(' AND ',$where):'';
$items=$db->all("SELECT c.*,o.titulo oferta_titulo FROM portal_consultas c LEFT JOIN ofertas o ON o.id=c.oferta_id $condition ORDER BY c.created_at DESC LIMIT 200",$types,$params);$labels=['nueva'=>'Pendiente','leida'=>'Atendida','respondida'=>'Respondida'];
?>
<section class="admin-page"><div class="container-fluid px-3 px-lg-4"><div class="mb-4"><h1 class="h3 mb-1">Contactos</h1><p class="text-secondary">Consultas generales y solicitudes sobre ofertas académicas.</p></div><form id="contacts-filter" class="card admin-card mb-4"><div class="card-body row g-2"><div class="col-md-5"><select class="form-select" name="estado"><option value="">Todos los estados</option><?php foreach($labels as $value=>$label):?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-5"><select class="form-select" name="tipo"><option value="">Todos los orígenes</option><option value="contacto" <?=$type==='contacto'?'selected':''?>>Consulta general</option><option value="oferta" <?=$type==='oferta'?'selected':''?>>Oferta académica</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filtrar</button></div></div></form><div class="card admin-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Fecha</th><th>Contacto</th><th>Tema y mensaje</th><th>Estado</th><th>Gestión</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="5" class="text-center py-5">No hay solicitudes.</td></tr><?php endif;?><?php foreach($items as $item):?><tr><td><?=date('d/m/Y H:i',strtotime($item['created_at']))?></td><td><strong><?=app_escape($item['nombre'])?></strong><small class="d-block"><?=app_escape($item['email'])?></small><small><?=app_escape($item['telefono'])?></small></td><td><strong><?=app_escape($item['asunto']?:$item['oferta_titulo'])?></strong><details><summary>Ver mensaje</summary><p class="mt-2"><?=nl2br(app_escape($item['mensaje']))?></p></details></td><td><span class="badge <?=$item['estado']==='respondida'?'text-bg-success':($item['estado']==='leida'?'text-bg-info':'text-bg-warning')?>"><?=app_escape($labels[$item['estado']]??$item['estado'])?></span></td><td><div class="btn-group btn-group-sm"><button class="btn btn-outline-info" title="Atendida" onclick="contactsAction('attend',<?=(int)$item['id']?>)"><i class="bi bi-eye"></i></button><button class="btn btn-outline-success" title="Respondida" onclick="contactsAction('respond',<?=(int)$item['id']?>)"><i class="bi bi-check2"></i></button><button class="btn btn-outline-secondary" title="Reabrir" onclick="contactsAction('reopen',<?=(int)$item['id']?>)"><i class="bi bi-arrow-counterclockwise"></i></button><a class="btn btn-outline-primary" href="mailto:<?=app_escape($item['email'])?>?subject=<?=rawurlencode('Respuesta ISFD: '.($item['asunto']?:'su consulta'))?>"><i class="bi bi-envelope"></i></a></div></td></tr><?php endforeach;?></tbody></table></div></div></div></section><script>function contactsReload(){cargar_post('modulos/contactos/php/app_home.php','content_seccion',$('#contacts-filter').serialize())}function contactsAction(action,id){appAction('modulos/contactos/php/app_action.php',{action:action,id:id},contactsReload)}$('#contacts-filter').on('submit',function(e){e.preventDefault();contactsReload()});</script>
